  4	const ROUND_DURATION_SECONDS = 50;
  5	const URGENT_THRESHOLD_SECONDS = 10;
  6	const TIME_EPSILON_SECONDS = 0.000001;
  7	const MAX_FRAME_DELTA_SECONDS = 0.05;
  8	const PICKUP_RADIUS_PX = 14;
  9	const INITIAL_SHELL_COUNT = 6;
 10	
 11	const canvas = document.getElementById("game");
 12	const ctx = canvas.getContext("2d");
 13	const shellCountElement = document.getElementById("shells");
 14	const tideElement = document.getElementById("tide");
 15	const tideStatusElement = document.getElementById("tide-status");
 16	const tideBarElement = document.getElementById("tide-bar");
 17	const resultElement = document.getElementById("result");
 18	const hudElement = document.getElementById("hud");
 19	
 20	const player = { x: 240, y: 160, speed: 120 };
 21	let shellCount = 0;
 22	let remainingSeconds = ROUND_DURATION_SECONDS;
 23	let roundState = "playing";
 24	const shells = [];
 25	
 26	// 供后续刷新与掉落系统接入结算边界；本任务不新增持续刷新机制。
 27	let shellSpawnTimer = null;
 28	const activeRecoveries = [];
 29	
 30	function spawnShell() {
 31	  if (roundState !== "playing") return false;
 32	  shells.push({
 33	    x: 20 + Math.random() * (canvas.width - 40),
 34	    y: 20 + Math.random() * (canvas.height - 40),
 35	  });
 36	  return true;
 37	}
 38	
 39	function collect(shell) {
 40	  if (roundState !== "playing") return;
 41	  const idx = shells.indexOf(shell);
 42	  if (idx < 0) return;
 43	  shells.splice(idx, 1);
 44	  shellCount += 1;
 45	  shellCountElement.textContent = String(shellCount);
 46	}
 47	
 48	function updateTideHud() {
 49	  const displaySeconds = Math.ceil(Math.max(0, remainingSeconds - TIME_EPSILON_SECONDS));
 50	  const remainingRatio = remainingSeconds / ROUND_DURATION_SECONDS;
 51	  const isUrgent = remainingSeconds > 0
 52	    && remainingSeconds <= URGENT_THRESHOLD_SECONDS + TIME_EPSILON_SECONDS;
 53	
 54	  tideElement.textContent = String(displaySeconds);
 55	  tideBarElement.style.width = `${Math.max(0, remainingRatio) * 100}%`;
 56	  tideBarElement.parentElement.setAttribute("aria-valuenow", String(displaySeconds));
 57	  tideStatusElement.classList.toggle("urgent", isUrgent);
 58	  hudElement.classList.toggle("urgent", isUrgent);
 59	  tideStatusElement.textContent = isUrgent ? "即将涨潮！" : "距涨潮";
 60	}
 61	
 62	function settleRound() {
 63	  if (roundState === "settled") return;
 64	  roundState = "settled";
 65	
 66	  if (shellSpawnTimer !== null) {
 67	    clearInterval(shellSpawnTimer);
 68	    shellSpawnTimer = null;
 69	  }
 70	  activeRecoveries.length = 0;
 71	  for (const key of Object.keys(keys)) keys[key] = false;
 72	
 73	  updateTideHud();
 74	  resultElement.hidden = false;
 75	  resultElement.textContent = `潮汐结算：拾取总数 ${shellCount} 枚`;
 76	}
 77	
 78	function update(dt) {
 79	  if (roundState !== "playing") return;
 80	
 81	  const nextRemainingSeconds = remainingSeconds - dt;
 82	  remainingSeconds = nextRemainingSeconds <= TIME_EPSILON_SECONDS ? 0 : nextRemainingSeconds;
 83	  updateTideHud();
 84	  if (remainingSeconds === 0) {
 85	    settleRound();
 86	    return;
 87	  }
 88	
 89	  if (keys.ArrowLeft) player.x -= player.speed * dt;
 90	  if (keys.ArrowRight) player.x += player.speed * dt;
 91	  if (keys.ArrowUp) player.y -= player.speed * dt;
 92	  if (keys.ArrowDown) player.y += player.speed * dt;
 93	  player.x = Math.max(10, Math.min(canvas.width - 10, player.x));
 94	  player.y = Math.max(7, Math.min(canvas.height - 7, player.y));
 95	
 96	  for (const shell of [...shells]) {
 97	    if (Math.hypot(shell.x - player.x, shell.y - player.y) < PICKUP_RADIUS_PX) {
 98	      collect(shell);
 99	    }
100	  }
101	}
102	
103	const keys = {};
104	window.addEventListener("keydown", (event) => { keys[event.key] = true; });
105	window.addEventListener("keyup", (event) => { keys[event.key] = false; });
106	
107	let last = performance.now();
108	function frame(now) {
109	  const dt = Math.min(MAX_FRAME_DELTA_SECONDS, (now - last) / 1000);
110	  last = now;
111	  update(dt);
112	
113	  ctx.clearRect(0, 0, canvas.width, canvas.height);
114	  ctx.fillStyle = "#e8b04b";
115	  ctx.fillRect(player.x - 10, player.y - 7, 20, 14);
116	  ctx.fillStyle = "#f3f1e4";
117	  for (const shell of shells) {
118	    ctx.beginPath();
119	    ctx.arc(shell.x, shell.y, 6, 0, Math.PI * 2);
120	    ctx.fill();
121	  }
122	  requestAnimationFrame(frame);
123	}
124	
125	for (let i = 0; i < INITIAL_SHELL_COUNT; i += 1) spawnShell();
126	updateTideHud();
127	requestAnimationFrame(frame);

