const fs = require("fs");
const vm = require("vm");

const scriptPath = process.argv[2];
if (!scriptPath) {
  console.error("usage: node review-14-dom-smoke.js <main.js>");
  process.exit(2);
}

class ClassList {
  constructor() {
    this.values = new Set();
  }
  toggle(name, force) {
    if (force) this.values.add(name);
    else this.values.delete(name);
  }
  contains(name) {
    return this.values.has(name);
  }
}

function makeElement(id) {
  return {
    id,
    textContent: "",
    hidden: false,
    style: {},
    attrs: {},
    classList: new ClassList(),
    parentElement: null,
    setAttribute(name, value) {
      this.attrs[name] = String(value);
    },
    getAttribute(name) {
      return this.attrs[name];
    },
  };
}

const elements = {
  game: makeElement("game"),
  shells: makeElement("shells"),
  tide: makeElement("tide"),
  "tide-status": makeElement("tide-status"),
  "tide-bar": makeElement("tide-bar"),
  result: makeElement("result"),
  hud: makeElement("hud"),
};
elements.game.width = 480;
elements.game.height = 320;
elements.game.getContext = () => ({
  clearRect() {},
  fillRect() {},
  beginPath() {},
  arc() {},
  fill() {},
  set fillStyle(value) {},
});
const tideTrack = makeElement("tide-track");
elements["tide-bar"].parentElement = tideTrack;

let frameCallback = null;
let rafCount = 0;
const context = {
  console,
  Math,
  document: {
    getElementById(id) {
      return elements[id];
    },
  },
  window: {
    addEventListener() {},
  },
  performance: {
    now() {
      return 0;
    },
  },
  requestAnimationFrame(callback) {
    rafCount += 1;
    frameCallback = callback;
  },
  clearInterval() {},
};

vm.createContext(context);
vm.runInContext(fs.readFileSync(scriptPath, "utf8"), context, { filename: scriptPath });

function snap(label) {
  return `${label}: tide=${elements.tide.textContent} aria=${tideTrack.attrs["aria-valuenow"]} width=${elements["tide-bar"].style.width} urgentStatus=${elements["tide-status"].classList.contains("urgent")} urgentHud=${elements.hud.classList.contains("urgent")} resultHidden=${elements.result.hidden} result=${elements.result.textContent}`;
}

console.log(snap("initial"));
for (let now = 50; now <= 40000; now += 50) frameCallback(now);
console.log(snap("pt01@10s"));
for (let now = 40050; now <= 50000; now += 50) frameCallback(now);
console.log(snap("settled@0s"));
const settled = snap("after-settle");
for (let now = 50050; now <= 50300; now += 50) frameCallback(now);
console.log(`idempotent=${settled === snap("after-settle")}`);
console.log(`rafCount=${rafCount}`);

const ok =
  elements.tide.textContent === "0" &&
  tideTrack.attrs["aria-valuenow"] === "0" &&
  elements.result.hidden === false &&
  elements.result.textContent === "潮汐结算：拾取总数 0 枚";
if (!ok) process.exit(1);

